CREATE DATABASE IF NOT EXISTS payment_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE payment_db;
CREATE TABLE payment_transactions (id BINARY(16) NOT NULL, order_id BINARY(16) NOT NULL, customer_id BINARY(16) NOT NULL, provider ENUM('STRIPE','RAZORPAY','WALLET') NOT NULL, provider_payment_id VARCHAR(255), idempotency_key VARCHAR(128) NOT NULL, amount DECIMAL(19,4) NOT NULL, currency CHAR(3) NOT NULL, status ENUM('PENDING','AUTHORIZED','CAPTURED','FAILED','REFUNDED','CANCELLED') NOT NULL, failure_code VARCHAR(100), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_payment_order_idempotency(order_id,idempotency_key), UNIQUE KEY uk_provider_payment(provider,provider_payment_id), KEY ix_payment_customer(customer_id,created_at), KEY ix_payment_status(status,created_at), CONSTRAINT ck_payment_amount CHECK(amount > 0)) ENGINE=InnoDB;
CREATE TABLE webhook_receipts (id BINARY(16) NOT NULL, provider ENUM('STRIPE','RAZORPAY') NOT NULL, provider_event_id VARCHAR(255) NOT NULL, signature_valid BOOLEAN NOT NULL, payload JSON NOT NULL, received_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), processed_at TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_webhook_provider_event(provider,provider_event_id), KEY ix_webhook_pending(processed_at,received_at)) ENGINE=InnoDB;
CREATE TABLE wallet_accounts (id BINARY(16) NOT NULL, customer_id BINARY(16) NOT NULL, currency CHAR(3) NOT NULL, balance DECIMAL(19,4) NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(id), UNIQUE KEY uk_wallet_customer_currency(customer_id,currency), CONSTRAINT ck_wallet_balance CHECK(balance >= 0)) ENGINE=InnoDB;
CREATE TABLE ledger_entries (id BINARY(16) NOT NULL, wallet_account_id BINARY(16) NOT NULL, payment_transaction_id BINARY(16), entry_type ENUM('CREDIT','DEBIT','REFUND','ADJUSTMENT') NOT NULL, amount DECIMAL(19,4) NOT NULL, balance_after DECIMAL(19,4) NOT NULL, reference_type VARCHAR(80) NOT NULL, reference_id BINARY(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_ledger_reference(reference_type,reference_id,entry_type), KEY ix_ledger_account_created(wallet_account_id,created_at), CONSTRAINT ck_ledger_amount CHECK(amount > 0), CONSTRAINT fk_ledger_wallet FOREIGN KEY(wallet_account_id) REFERENCES wallet_accounts(id), CONSTRAINT fk_ledger_payment FOREIGN KEY(payment_transaction_id) REFERENCES payment_transactions(id)) ENGINE=InnoDB;
CREATE TABLE outbox_event (id BINARY(16) NOT NULL, aggregate_type VARCHAR(80) NOT NULL, aggregate_id BINARY(16) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSON NOT NULL, occurred_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at TIMESTAMP(6), attempts INT NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_outbox_unpublished(published_at,occurred_at)) ENGINE=InnoDB;
